\begin{document}

\section*{অধ্যায় ৮}
\textbf{মানব শারীরতত্ত্ব: সমন্বয় ও নিয়ন্ত্রণ}
(HUMAN PHYSIOLOGY: COORDINATION AND CONTROL)

\begin{multicols}{2}

\textbf{অন্যান্য সকল প্রাণীর মতো মানুষ ও দেহের বাহ্যিক ও অভ্যন্তরীন পরিবর্তনের সাথে সাথে আচরণগত পরিবর্তন সাধন করে। এটি দেহের সাম্যবাহ্য রক্ষা এবং অস্তিত্ব রক্ষার জন্য অত্যাবশ্যকীয় ঘটনা। দেহের বিভিন্ন পরিবর্তন দেহস্থ আতংকোক্ষীয় সমন্বয় দ্বারা পরিচালিত হয়। দেহের আতংকোক্ষীয় সমন্বয় প্রধান দুটি উপায়ে সংযুক্ত হয়, যথা- স্নায়বিক সমন্বয় (neural coordination) এবং রাসায়নিক সমন্বয় (chemical coordination)। এ অধ্যায়ে মানবদেহের সমন্বয় ব্যবস্থা এবং এদের নিয়ন্ত্রণ সম্পর্কে আলোচনা করা হয়েছে।

\textbf{প্রধান শব্দাবলি (Keywords)}

\begin{itemize}[noitemsep]
    \item নিউরন
    \item সিন্যাপস
    \item করোটিক স্লায়
    \item রিফ্রাক্টরি পিরিয়ড
    \item নিউরোট্রাসমিটার
    \item ইউটেশিয়ান নালি
    \item অর্গান অব কর্টি
    \item স্টেরিওকোপিক দৃষ্টি
    \item কর্নিয়া
    \item কোরোয়েড
    \item রেটিনা
    \item হরমোন
\end{itemize}

\textbf{পরিষ্কার সংখ্যা ১২। এ অধ্যায় পাঠ শেষে শিক্ষার্থী যা পারবে}

\begin{tabularx}{\linewidth}{|X|X|}
\hline
\textbf{শিখনফল} & \textbf{বিষয়বস্তু} \\
\hline
1. স্নায়বিক সমন্বয়ের ধারণা ব্যাখ্যা করতে পারবে। & \textbullet স্নায়বিক সমন্বয় \\
2. মস্তিষ্কের প্রধান অংশের কাজ ব্যাখ্যা করতে পারবে। & \textbullet ধারণা \\
3. মানুষের বিভিন্ন জৈবিক কার্যক্রমে করোটিক স্লায়ের ভূমিকা বিশ্লেষণ করতে পারবে। & \textbullet করোটিক স্লায় (উৎপত্তি, প্রকৃতি ও কাজ) \\
4. মানব সংবেদী অঙ্গসমূহের গঠনের সাথে কাজের সম্পর্ক তুলনা করতে পারবে। & \textbullet মানব সংবেদী অঙ্গ \\
 & \textbullet চোখ (গঠন ও কাজ) \\
 & \textbullet কান (গঠন ও কাজ) \\
 & \textbullet রাসায়নিক সমন্বয় \\
\hline
\end{tabularx}

\end{multicols}

\end{document}

