$$\text{জীববিজ্ঞান দ্বিতীয় পত্র}$$
$$\text{মানব শরীরতন্ত্র: সমন্বয় ও নিয়ন্ত্রণ}$$
$$\text{২৫৪}$$
\textbf{১। বিভিন্ন সংবেদী উপাত্ত (sensory data) সংগ্রহ ও প্রতিবেদন সৃষ্টি করা স্নায়ুতন্ত্রের প্রধান কাজ। স্নায়ুতন্ত্র যেসব সংবেদী উপাত্তের প্রতি সাড়া দেয় সেগুলো হলো-}
\begin{itemize}
    \item দেহতল ঘারা-গরম, ঠাণ্ডা, স্পর্শ, ঢাপ, ব্যথা ইত্যাদি।
    \item দূরবর্তী ঘটনা- গন্ধ, আলো, শব্দ ইত্যাদি।
    \item দেহভাগের- উজ্জ্বলনা, মানসিক ঢাপ, ব্যথা, রক্তচাপ, রক্তে খ্যান গ্যাস, হরমোন ও গ্লুকোজের মাতা।
\end{itemize}
\textbf{২। স্নায়ুতন্ত্র দেহের বিভিন্ন চেষ্টায় (motor) কাজ নিয়ন্ত্রণ করে, যেমন- (i) সকল পেশির সঞ্চন-প্রসারণ; (ii) সকল গ্রহির ক্ষরণ; (iii) সকল আত্মরক্ষায় (visceral) অঙ্গের কার্যকলাপ ইত্যাদি।

\textbf{স্নায়ুতন্ত্রের প্রকারভেদ}

\textbf{১। অঙ্গসংস্থানিক দিক থেকে মানুষের স্নায়ুতন্ত্র দুইভাগে বিভক্ত, যথা-}
\begin{enumerate}
    \item \textbf{(ক) কেন্দ্রীয় স্নায়ুতন্ত্র (Central nervous system-CNS):} এটি মস্তিষ্ক (brain) এবং স্পুষ্টকাণ্ড (spinal cord) নিয়ে গঠিত। মস্তিষ্ক স্নায়ুতন্ত্রের সবচেয়ে জটিল অংশ। এটি ক্রানিয়াম (cranium) মধ্যে সুরক্ষিত থাকে এবং নিউরন (100 বিলিয়ন), নিউরোগ্লিয়া ও এপোনডাইমা সমন্বিত নিউরাল কলা দ্বারা গঠিত। এর অভ্যন্তরে তরলপূর্ণ চারটি গহ্বর বা ভেত্রিক্ল থাকে। মস্তিষ্কের পেছন হতে একটি তরলপূর্ণ নালি স্পুষ্টকাণ্ড (spinal cord) সৃষ্ট হয়ে সমস্ত মেরুদণ্ড বরাবর প্রসারিত থাকে। এটি মেরুদণ্ডের নিউরাল আর্চ দ্বারা সুরক্ষিত থাকে এবং নিউরন (1 বিলিয়ন), শ্বয়ান কোষ (Schwann cell) ও সেটেলাইট কোষ (settelite cell) সমন্বিত নিউরাল কলা দ্বারা গঠিত। কেন্দ্রীয় স্নায়ুতন্ত্র মেনিনজেস (meninges) নামক দূর ও মজবুত পদ্ধা দ্বারা আবৃত থাকে। মস্তিষ্কের গহ্বর ও স্পুষ্টকাণ্ডের নালিতে (নিউরাল নালি) বিদ্যমান তরলকে সেরিব্রোস্পাইনাল ফ্লুইড (cerebrospinal fluid) বলে। কেন্দ্রীয় স্নায়ুতন্ত্র প্রাথমিক স্নায়ুতন্ত্র হতে সংবেদ গ্রহণ করে এবং উপযুক্ত প্রতিবেদন তৈরি করে।
    \item \textbf{(খ) প্রাথমিক স্নায়ুতন্ত্র (Peripheral nervous system-PNS):} কেন্দ্রীয় স্নায়ুতন্ত্রের বাইরে অবস্থিত সকল স্নায়ু এবং
\end{enumerate}

---

\textbf{স্নায়ুক্লার গঠন (Structure of nervous tissue)}

\textbf{স্নায়ুক্লা দিয়ে স্নায়ুত্ত্ব গঠিত। নিউরন (neurone) নামক একটি কোষ দিয়ে স্নায়ুক্লা গঠিত। তবে কেন্দ্রীয় স্নায়ুত্ত্বে নিউরনকে অবলম্বন দেয়ার জন্য নিউরোগ্লিয়া (neuroglia) নামক বিশেষ ধরনের কোলা থাকে।}

\textbf{নিউরন (Neuron)}

\textbf{স্নায়ুত্ত্বের সকল কার্যবলি উহার গঠনিক উপাদান নিউরন কোষ দ্বারা সম্পাদিত হয়। প্রতিটি নিউরনই কাজের দিক থেকে একটি ক্ষুদ্র মস্তিষ্কের সমতুল্য। তাই নিউরনকে স্নায়ুত্ত্বের গঠনগত ও কার্যগত একক বলা হয়। সাধারণ কোষের মতো।

